/// System information service
/// Provides machine configuration and identity information
///
/// To build a server, implement a class that conforms to this protocol.
internal protocol Beebium_SystemServiceProvider: CallHandlerProvider {
  var interceptors: Beebium_SystemServiceServerInterceptorFactoryProtocol? { get }

  /// Get current system/machine information
  func getSystemInfo(request: Beebium_GetSystemInfoRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_SystemInfo>

  /// Set the machine's name template (a plain name is a template with no
  /// placeholders). See MachineIdentity.name_template.
  func setMachineName(request: Beebium_SetMachineNameRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_SetMachineNameResponse>

  /// List the placeholders a name template can use on this server, with
  /// their current values. Clients carry no list of keys; they ask.
  func listNamePlaceholders(request: Beebium_ListNamePlaceholdersRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_ListNamePlaceholdersResponse>

  /// Render a name template against the current values without changing
  /// anything, for a live preview while the user edits.
  func previewMachineName(request: Beebium_PreviewMachineNameRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_PreviewMachineNameResponse>

  /// Subscribe to server status events (shutdown notifications, identity changes, etc.)
  /// Server sends READY immediately upon subscription, then status changes.
  /// Stream ends when server shuts down or client disconnects.
  func watchServerStatus(request: Beebium_WatchServerStatusRequest, context: StreamingResponseCallContext<Beebium_ServerStatusEvent>) -> EventLoopFuture<GRPCStatus>

  /// Request server shutdown.
  /// Returns whether the request was accepted based on shutdown policy.
  /// Policy: accept if requester's instance UUID matches launch provenance,
  ///         or only one client connected, or --allow-shutdown flag was set.
  func requestShutdown(request: Beebium_ShutdownRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_ShutdownResponse>

  /// Get current mDNS service advertisement state
  func getAdvertisementState(request: Beebium_GetAdvertisementStateRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_GetAdvertisementStateResponse>

  /// Enable or disable mDNS service advertisement at runtime
  func setAdvertisement(request: Beebium_SetAdvertisementRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_SetAdvertisementResponse>

  /// Get current pacing statistics (PI controller state, timing, I/O skip counts).
  func getPacingStats(request: Beebium_GetPacingStatsRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_PacingStats>

  /// Stream pacing statistics at a configurable interval.
  func watchPacingStats(request: Beebium_WatchPacingStatsRequest, context: StreamingResponseCallContext<Beebium_PacingStats>) -> EventLoopFuture<GRPCStatus>

  /// Set the runtime pacing speed multiplier.
  func setSpeedMultiplier(request: Beebium_SetSpeedMultiplierRequest, context: StatusOnlyCallContext) -> EventLoopFuture<Beebium_SetSpeedMultiplierResponse>
}

